draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // wisdom circle
  ctx.beginPath();
  ctx.arc(W/2, H/2-200, 30+20*Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // lesson lines
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50);
  ctx.lineTo(W/2+50+30*Math.cos(t), H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50);
  ctx.lineTo(W/2-50-30*Math.cos(t), H/2);
  ctx.stroke();

  // life circle
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20+10*Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // applying lines
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+30+20*Math.cos(t), H/2+100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2-30-20*Math.cos(t), H/2+100);
  ctx.stroke();

  ctx.restore();
}
